two data regions: KV data at `data_offset`, scale data at `scale_offset`. both 4096-aligned for DMA. scale region only present when `scale_block_size_bytes > 0` (FP8 quantization enabled). this mirrors `BlockCopyEngine._combine_lists()` which pairs KV and scale tensors for lockstep transfer.

`data_offset` = `align_up(sizeof(ShmHeader) + N * sizeof(BlockMeta), 4096)`.
`scale_offset` = `align_up(data_offset + N * block_size_bytes, 4096)`.

```c
struct ShmHeader {
  uint64_t magic;    // 0x4B564D475348_4D00 ("KVMGSHM\0")
  uint32_t version;  // 1
  uint32_t num_blocks;
  uint32_t block_size_bytes;
  uint32_t num_layers;
  uint32_t page_size;
  uint32_t inner_dim;  // num_kv_heads × head_dim × 2 (K+V)
  uint64_t data_offset;
  uint32_t scale_block_size_bytes;  // 0 if no quantization
  uint32_t
      quantization_granularity;  // head_dim chunks per scale, 0 if unquantized
  uint32_t scale_dtype;          // 0=none, 1=float32
  uint32_t _pad;
  uint64_t scale_offset;  // 0 if no quantization
  BlockMeta blocks[];     // flexible array member
};

struct BlockMeta {
  _Atomic uint32_t state;
  _Atomic uint32_t ref_count;
  uint64_t sequence_hash;
  uint64_t prefix_hash;
  uint32_t num_tokens;
  uint32_t owner_pid;
  uint64_t last_access_ns;
  uint32_t frequency;
  uint32_t _pad;
};
```

#### ownership and creation

manager creates the shm at startup. engine opens it ONLY after [handshake](/thoughts/KV-connector#lifecycle-shm-handshake) completes with `status=OK`.

the engine shouldn't touch the shm until the manager confirms it's fully initialized.

**ordering invariant**: manager must complete ALL of the following before binding its ROUTER socket (which enables INIT_REQ reception):

```python
class ShmPool:
  def __init__(self, path: str, create: bool, **kwargs):
    if create:
      (
        total_size,
        data_offset,
        block_size_bytes,
        scale_offset,
        scale_block_size_bytes,
      ) = compute_layout(...)
      fd = os.open(path, os.O_CREAT | os.O_RDWR, 0o600)
      os.ftruncate(fd, total_size)
      self._mm = mmap.mmap(fd, total_size)
      # write ShmHeader + init BlockMeta
    else:
      fd = os.open(path, os.O_RDWR)
      self._mm = mmap.mmap(fd, 0)
      # validate magic + version
    self.header = ShmHeader.from_buffer(self._mm)

  @property
  def data_ptr(self) -> int:
    return ctypes.addressof(
      ctypes.c_char.from_buffer(self._mm, self.header.data_offset)
    )

  @property
  def scale_data_ptr(self) -> int | None:
    if self.header.scale_offset == 0:
      return None
    return ctypes.addressof(
      ctypes.c_char.from_buffer(self._mm, self.header.scale_offset)
    )

  def block_meta(self, idx: int) -> BlockMeta:
    offset = ctypes.sizeof(ShmHeader) + idx * ctypes.sizeof(BlockMeta)
    return BlockMeta.from_buffer(self._mm, offset)
```

`TransferExecutor` takes `ShmPool.data_ptr` (and optionally `scale_data_ptr`) and wraps as Buffers, mirroring `BlockCopyEngine._combine_lists()`:

```
engine (DEALER) ──ipc:///tmp/kv-ctrl── manager (ROUTER)

LOOKUP_REQ  { prefix_hashes: [u64] }
LOOKUP_RESP { block_ids: [u32], tiers: [u8] }

ALLOC_REQ   { num_blocks: u32 }
ALLOC_RESP  { shm_block_ids: [u32], status: u8 }

FREE_REQ    { request_id: u64 }
FREE_RESP   { ack: bool }
```

**socket 2: PUSH/PULL** (async store notifications)

i.e. after the engine finishes DMA to shm and flip `BlockMeta.state` to COMMITTED via atomic CAS, then push `STORE_NOTIFY`.

```
engine (PUSH) ──ipc:///tmp/kv-data── manager (PULL)

STORE_NOTIFY { block_id: u32, sequence_hash: u64 }
```

engine writes KV to shm, flips `BlockMeta.state` to COMMITTED, pushes notification. manager touches data only after COMMITTED. zero-copy.[^16]

**socket 3: PUB/SUB** (lifecycle/event broadcasting)

```
manager (PUB) ──ipc:///tmp/kv-events── engine(s) (SUB)

EVICT_EVENT { block_ids: [u32] }
```

```python
class ExternalKVConnector:
  def __init__(
    self,
    endpoint: str,
    shm_path: str,
    params: KVCacheParams,
    devices: Sequence[Device],
    device_tensors: list[Buffer],
    device_scale_tensors: list[Buffer] | None = None,
  ):
    self._ctrl = zmq.Context().socket(zmq.DEALER)
    self._ctrl.connect(f'ipc://{endpoint}/ctrl')
    self._data = zmq.Context().socket(zmq.PUSH)
    self._data.connect(f'ipc://{endpoint}/data')
    self._events = zmq.Context().socket(zmq.SUB)
    self._events.connect(f'ipc://{endpoint}/events')
    self._events.subscribe(b'')
    self._shm = ShmPool(shm_path, create=False)
    self._device_tensors = device_tensors
    self._device_scale_tensors = device_scale_tensors
    self._block_size = params.page_size
    block_shape = params.shape_per_block
    scale_block_shape = None
    scale_dtype = None
    if params.kvcache_quant_config is not None:
      scale_block_shape = params.shape_per_scale_block
      scale_dtype = params.kvcache_quant_config.scale_dtype
    self._xfer = TransferExecutor(
      shm_pool=self._shm,
      device_tensors=device_tensors,
      device_scale_tensors=device_scale_tensors,
      block_shape=block_shape,
      scale_block_shape=scale_block_shape,
      dtype=params.cache_dtype,
      scale_dtype=scale_dtype,
    )
    self._pending_saves: list[tuple[int, int]] = []
    self._pending_loads: dict[str, list[tuple[int, int]]] = {}
    self._metrics = KVCacheMetrics()

  @property
  def name(self) -> str:
    return 'ExternalKVConnector'

  def lookup(self, ctx: TextGenerationContext, block_hashes: list[int]) -> int:
    if not block_hashes:
      return 0
    self._ctrl.send(
      msgpack.packb({
        'type': 'LOOKUP_REQ',
        'prefix_hashes': block_hashes,
        'max_blocks': len(block_hashes),
      })
    )
    resp = msgpack.unpackb(self._ctrl.recv())
    matched = resp['matched']
    if matched > 0:
      self._pending_loads[str(ctx.request_id)] = [
        (block_hashes[i], resp['shm_block_ids'][i]) for i in range(matched)
      ]
    return matched * self._block_size

  def load(
    self,
    ctx: TextGenerationContext,
    target_block_ids: list[int],
    device_tensors: list[Buffer],
  ) -> list[int]:
    request_id = str(ctx.request_id)
    pending = self._pending_loads.pop(request_id, None)
    if not pending or not target_block_ids:
      return []
    num_to_load = min(len(pending), len(target_block_ids))
    loaded_hashes = []
    for i in range(num_to_load):
      block_hash, shm_bid = pending[i]
      device_bid = target_block_ids[i]
      meta = self._shm.block_meta(shm_bid)
      assert atomic_load(meta.state) == COMMITTED
      atomic_store(meta.state, READING)
      self._xfer.load_block(device_bid, shm_bid)
      loaded_hashes.append(block_hash)
    self._metrics.h2d_blocks_copied += num_to_load
    return loaded_hashes

  def save(self, block_ids: list[int], block_hashes: list[int]) -> None:
    for bid, h in zip(block_ids, block_hashes, strict=True):
      self._pending_saves.append((bid, h))

  def flush(self) -> None:
    if not self._pending_saves:
      return
    self._ctrl.send(
      msgpack.packb({
        'type': 'ALLOC_REQ',
        'num_blocks': len(self._pending_saves),
      })
    )
    resp = msgpack.unpackb(self._ctrl.recv())
    shm_block_ids = resp['shm_block_ids']
    for (device_bid, block_hash), shm_bid in zip(
      self._pending_saves, shm_block_ids
    ):
      meta = self._shm.block_meta(shm_bid)
      atomic_store(meta.state, FILLING)
      self._xfer.save_block(device_bid, shm_bid)
    for (device_bid, block_hash), shm_bid in zip(
      self._pending_saves, shm_block_ids
    ):
      meta = self._shm.block_meta(shm_bid)
      atomic_store(meta.state, COMMITTED)
      atomic_store(meta.sequence_hash, block_hash)
    self._data.send(
      msgpack.packb({
        'type': 'STORE_NOTIFY',
        'shm_block_ids': shm_block_ids,
        'hashes': [h for _, h in self._pending_saves],
      })
    )
    self._metrics.d2h_blocks_copied += len(self._pending_saves)
    self._pending_saves.clear()

  def sync(self) -> None:
    self._xfer.wait_for_completion()
    for request_id, pending in self._pending_loads.items():
      for _, shm_bid in pending:
        atomic_store(self._shm.block_meta(shm_bid).state, FREE)

  def on_request_complete(
    self, request_id: RequestID, block_ids: list[int]
  ) -> None:
    self._pending_loads.pop(str(request_id), None)
    self._ctrl.send(
      msgpack.packb({'type': 'FREE_REQ', 'request_id': int(request_id)})
    )

  def shutdown(self) -> None:
    self._xfer.wait_for_completion()
    self._ctrl.close()
    self._data.close()
    self._events.close()

  @property
  def num_host_blocks(self) -> int:
    return self._shm.header.num_blocks

  @property
  def num_used_host_blocks(self) -> int:
    return sum(
      1
      for i in range(self._shm.header.num_blocks)
      if atomic_load(self._shm.block_meta(i).state) != FREE
    )

  @property
  def host_tensors(self) -> list[Buffer] | None:
    return None

  @property
  def host_scale_tensors(self) -> list[Buffer] | None:
    return None

  def reset_prefix_cache(self) -> None:
    self._ctrl.send(msgpack.packb({'type': 'RESET_CACHE'}))
    self._ctrl.recv()
    self._pending_loads.clear()
    self._pending_saves.clear()

  @property
  def metrics(self) -> KVCacheMetrics:
    return KVCacheMetrics(
      h2d_blocks_copied=self._metrics.h2d_blocks_copied,
      d2h_blocks_copied=self._metrics.d2h_blocks_copied,
    )
